svg.script:
(function(){
  var deferred = null;
  var $ = function(id){ return document.getElementById(id); };

  try {
    var l = document.createElementNS('http://www.w3.org/1999/xhtml','link');
    l.setAttribute('rel','manifest'); l.setAttribute('href','manifest.webmanifest');
    document.documentElement.appendChild(l);
  } catch(e){}

  if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw.js').catch(function(){});

  window.addEventListener('beforeinstallprompt', function(e){ e.preventDefault(); deferred = e; });
  window.addEventListener('appinstalled', function(){
    $('banner').classList.remove('open');
    $('note').textContent = 'Installed! Find Supreme in your app launcher.';
    deferred = null;
  });

  $('getBtn').onclick = function(){
    if (window.matchMedia('(display-mode: standalone)').matches) { $('note').textContent = 'Already running as an app.'; return; }
    if (!deferred) { $('note').textContent = 'Auto-install not available. Use the Chrome menu (three dots) > Cast, save, and share > Install page as app.'; return; }
    $('banner').classList.add('open');
  };
  $('cancelBtn').onclick = function(){ $('banner').classList.remove('open'); };
  $('installBtn').onclick = function(){
    if (!deferred) return;
    $('banner').classList.remove('open');
    deferred.prompt();
    deferred.userChoice.then(function(){ deferred = null; });
  };
})();
